export type requestOtpResponse = (requestOtpResponseSuccess | requestOtpResponseError)

export const getRequestOtpUrl = () => {




  return `/auth/request-otp`
}

/**
 * @summary Request a one-time password by phone or email
 */
export const requestOtp = async (requestOtpBody: RequestOtpBody, options?: RequestInit): Promise<requestOtpResponse> => {

  const res = await fetch(getRequestOtpUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(requestOtpBody)
  }
)


  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: requestOtpResponse['data'] = body ? JSON.parse(body) : {}
  return { data, status: res.status, headers: res.headers } as requestOtpResponse
}



