export const getAdminAnalyticsUrl = (scope: 'revenue' | 'orders' | 'growth' | 'retention' | 'fleet' | 'operations' | 'gmv' | 'take_rate' | 'quality',
    params?: AdminAnalyticsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/admin/analytics/${scope}?${stringifiedParams}` : `/admin/analytics/${scope}`
}

