export type listProviderJobsResponseSuccess = (listProviderJobsResponse200) & {
  headers: Headers;
};
;

export type listProviderJobsResponse = (listProviderJobsResponseSuccess)

export const getListProviderJobsUrl = (params: ListProviderJobsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/dispatch/provider-jobs?${stringifiedParams}` : `/dispatch/provider-jobs`
}

